#ifndef ZEPHYR_SUBSYS_ZTEST_INCLUDE_ZTEST_TEST_H_
#define ZEPHYR_SUBSYS_ZTEST_INCLUDE_ZTEST_TEST_H_

#include <zephyr/kernel.h>
#include <zephyr/sys/util.h>
#include <zephyr/ztest.h>

#ifdef __cplusplus
extern "C" {
#endif

#if defined(CONFIG_USERSPACE)
#include <zephyr/app_memory/app_memdomain.h>
#define ZTEST_DMEM K_APP_DMEM
#define ZTEST_BMEM K_APP_BMEM
#else
#define ZTEST_DMEM
#define ZTEST_BMEM
#endif

/**
 * @brief Test case structure
 *
 * This structure defines a single test case.
 */
struct ztest_test_case {
	/** Name of the test case */
	const char *test_case_name;
	/** Function pointer to the test case */
	void (*test_fn)(void);
	/** Function pointer to setup/teardown function */
	void (*setup_teardown)(void);
};

/**
 * @brief Test suite structure
 *
 * This structure defines a test suite, which is a collection of test cases.
 */
struct ztest_test_suite {
	/** Name of the test suite */
	const char *name;
	/** Array of test cases in the suite */
	struct ztest_test_case *test_cases;
	/** Number of test cases in the suite */
	size_t num_test_cases;
};

/**
 * @brief Register a test suite
 *
 * This macro registers a test suite by placing a pointer to its structure
 * into a special linker section.
 *
 * @param name The name of the test suite.
 */
#define ZTEST_SUITE_REGISTER(name) \
	static const struct ztest_test_suite * const \
	__attribute__((__used__, __section__(".ztest_suites"))) \
	__ztest_##name##_ptr = &__ztest_##name##_suite;

/**
 * @brief Define a test case
 *
 * This macro defines a test case within a test suite. It is typically used
 * inside the ZTEST_SUITE macro.
 *
 * @param test_suite_name The name of the test suite this case belongs to.
 * @param test_case_name The name of the test case function.
 * @param setup_teardown_ptr A pointer to a setup/teardown function, or NULL.
 */
#define ZTEST_CASE(test_suite_name, test_case_name, setup_teardown_ptr) \
	{ \
		.test_case_name = #test_case_name, \
		.test_fn = test_case_name, \
		.setup_teardown = setup_teardown_ptr, \
	},

/**
 * @brief Define a test case with default setup/teardown
 *
 * This macro defines a test case with a NULL setup/teardown function.
 *
 * @param test_suite_name The name of the test suite this case belongs to.
 * @param test_case_name The name of the test case function.
 */
#define ZTEST_TEST(test_suite_name, test_case_name) \
	ZTEST_CASE(test_suite_name, test_case_name, NULL)

/**
 * @brief Define a test suite
 *
 * This macro defines a test suite and registers it. It takes a list of
 * ZTEST_CASE or ZTEST_TEST macros as variadic arguments.
 *
 * @param name The name of the test suite.
 * @param ... A list of ZTEST_CASE or ZTEST_TEST macros.
 */
#define ZTEST_SUITE(name, ...) \
	static struct ztest_test_case __attribute__((__used__)) \
	__ztest_##name##_cases[] = { \
		__VA_ARGS__ \
	}; \
	static struct ztest_test_suite __attribute__((__used__)) \
	__ztest_##name##_suite = { \
		.name = #name, \
		.test_cases = __ztest_##name##_cases, \
		.num_test_cases = ARRAY_SIZE(__ztest_##name##_cases), \
	}; \
	ZTEST_SUITE_REGISTER(name)

#ifdef __cplusplus
}
#endif

#endif /* ZEPHYR_SUBSYS_ZTEST_INCLUDE_ZTEST_TEST_H_ */
